  Record drv_layoutA : Prop := DLA {
    dla_segs : hl_segs L = ASEGS;
    dla_malloc : hl_malloc L = 0x80740; dla_free : hl_free L = 0x8073c; dla_memcpy : icl_memcpy IL = 0x7ebb8;
