  Definition CWA (LB : list (Z * Z)) (a : Z) : Prop :=
    in_block LB a \/ bv_unsigned sp0 - 8388608 <= a < bv_unsigned sp0 \/ (exists lo hi, In (lo, hi) IMG_W_A /\ lo <= a < hi).

