Lemma rdn_tr : forall (M M' : word -> option byte) a (n : nat) bs,
  rdn ASEGS M (Z_to_bv 64 a) n = Some bs -> 0 <= a -> a + Z.of_nat n <= 2 ^ 64 ->
  (forall i, a <= i < a + Z.of_nat n -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i)) ->
  rdn ASEGS M' (Z_to_bv 64 a) n = Some bs.
